const TOPICS=[['Matemática básica e aritmética',['Divisibilidade','Números primos','MMC','MDC','Frações']],['Conjuntos',['União e interseção']],['Razão, proporção e porcentagem',['Porcentagem']],['Álgebra e expressões algébricas',['Produtos notáveis']],['Equações, inequações e sistemas',['Equações do 2º grau']],['Funções',['Afim','Quadrática','Modular','Exponencial','Logarítmica']],['Potenciação e radiciação',['Propriedades das potências']],['Logaritmos',['Definição de logaritmo']],['Progressões aritméticas e geométricas',['Progressão aritmética']],['Matrizes, determinantes e sistemas lineares',['Determinantes']],['Geometria plana',['Triângulos','Quadriláteros','Circunferências','Áreas','Semelhança']],['Geometria espacial',['Prismas']],['Geometria analítica',['Distância entre pontos']],['Trigonometria',['Razões trigonométricas','Ciclo trigonométrico','Identidades','Equações trigonométricas']],['Análise combinatória',['Combinações']],['Probabilidade',['Eventos equiprováveis']],['Estatística',['Média aritmética']],['Números complexos',['Unidade imaginária']],['Polinômios',['Teorema do resto']],['Matemática financeira',['Juros compostos']]];
const raw=[
[0,'MMC','Fácil','Qual é o mínimo múltiplo comum entre 12 e 18?',['6','24','36','72'],2,['Fatore os números: $12=2^2\\cdot3$ e $18=2\\cdot3^2$.','Escolha o maior expoente de cada fator: $\\operatorname{MMC}=2^2\\cdot3^2=36$.']],
[1,'União e interseção','Fácil','Se $A=\\{1,2,3\\}$ e $B=\\{3,4\\}$, qual é $A\\cap B$?',['$\\{1,2,3,4\\}$','$\\{3\\}$','$\\{1,2\\}$','$\\varnothing$'],1,['A interseção contém os elementos comuns aos dois conjuntos.','O único elemento presente em A e B é 3. Logo, $A\\cap B=\\{3\\}$.']],
[2,'Porcentagem','Fácil','Um material custa R$ 200,00 e recebe desconto de 15%. Qual é o preço final?',['R$ 150,00','R$ 170,00','R$ 185,00','R$ 190,00'],1,['O desconto é $200\\cdot0{,}15=30$ reais.','Subtraia do preço inicial: $200-30=170$ reais.']],
[3,'Produtos notáveis','Fácil','Qual expressão é equivalente a $(x+3)^2$?',['$x^2+9$','$x^2+3x+9$','$x^2+6x+9$','$x^2+6x+6$'],2,['Use $(a+b)^2=a^2+2ab+b^2$.','Substituindo: $(x+3)^2=x^2+6x+9$.']],
[4,'Equações do 2º grau','Média','Quais são as raízes de $x^2-5x+6=0$?',['−2 e −3','1 e 6','2 e 3','0 e 5'],2,['Fatore o polinômio: $(x-2)(x-3)=0$.','Um dos fatores deve ser zero. Assim, $x=2$ ou $x=3$.']],
[5,'Afim','Fácil','Para $f(x)=2x-3$, determine x quando $f(x)=11$.',['4','5','6','7'],3,['Escreva $2x-3=11$.','Some 3 e divida por 2: $2x=14\\Rightarrow x=7$.']],
[6,'Propriedades das potências','Fácil','Calcule $\\frac{2^5\\cdot2^3}{2^4}$.',['4','8','16','32'],2,['Some os expoentes no numerador: $2^5\\cdot2^3=2^8$.','Subtraia o expoente do denominador: $2^{8-4}=2^4=16$.']],
[7,'Definição de logaritmo','Fácil','Qual é o valor de $\\log_2 32$?',['4','5','8','16'],1,['Pela definição, $\\log_2 32=x$ equivale a $2^x=32$.','Como $2^5=32$, temos $x=5$.']],
[8,'Progressão aritmética','Média','Uma PA tem primeiro termo 4 e razão 3. Qual é o décimo termo?',['27','28','30','31'],3,['Use $a_n=a_1+(n-1)r$.','Logo, $a_{10}=4+9\\cdot3=31$.']],
[9,'Determinantes','Média','Calcule o determinante de $A=\\begin{pmatrix}2&1\\\\3&4\\end{pmatrix}$.',['5','8','11','14'],0,['Para uma matriz de ordem 2, calcule o produto da diagonal principal menos o da secundária.','$\\det(A)=2\\cdot4-1\\cdot3=8-3=5$.']],
[10,'Triângulos','Fácil','Um triângulo retângulo tem catetos 6 cm e 8 cm. Quanto mede a hipotenusa?',['7 cm','10 cm','12 cm','14 cm'],1,['Pelo teorema de Pitágoras, $h^2=6^2+8^2=100$.','Como a medida é positiva, $h=\\sqrt{100}=10$ cm.']],
[11,'Prismas','Fácil','Um paralelepípedo retângulo tem dimensões 3 cm, 4 cm e 5 cm. Qual é seu volume?',['12 cm³','20 cm³','47 cm³','60 cm³'],3,['O volume é o produto das três dimensões.','$V=3\\cdot4\\cdot5=60$ cm³.']],
[12,'Distância entre pontos','Média','Qual é a distância entre $A=(1,2)$ e $B=(4,6)$?',['3','4','5','7'],2,['Use $d=\\sqrt{(x_B-x_A)^2+(y_B-y_A)^2}$.','$d=\\sqrt{3^2+4^2}=\\sqrt{25}=5$.']],
[13,'Razões trigonométricas','Fácil','Qual é o valor de $\\sin 30^\\circ+\\cos 60^\\circ$?',['0','$\\frac{1}{2}$','1','$\\sqrt{3}$'],2,['Os valores notáveis são $\\sin 30^\\circ=\\frac12$ e $\\cos 60^\\circ=\\frac12$.','Somando, $\\frac12+\\frac12=1$.']],
[14,'Combinações','Média','De um grupo de 5 alunos, quantas duplas diferentes podem ser formadas?',['5','10','20','25'],1,['A ordem dos alunos da dupla não importa. Use combinações.','$\\binom52=\\frac{5!}{2!3!}=\\frac{5\\cdot4}{2}=10$.']],
[15,'Eventos equiprováveis','Média','Dois dados comuns e independentes são lançados. Qual a probabilidade de a soma ser 7?',['$\\frac1{12}$','$\\frac19$','$\\frac16$','$\\frac14$'],2,['Existem $6\\cdot6=36$ pares equiprováveis.','Os pares favoráveis são (1,6), (2,5), (3,4), (4,3), (5,2) e (6,1).','$P=\\frac6{36}=\\frac16$.']],
[16,'Média aritmética','Fácil','A média aritmética de 4, 6 e 8 é igual a 6. Julgue a afirmação.',['Certo','Errado'],0,['Some os valores e divida pela quantidade: $\\bar{x}=\\frac{4+6+8}{3}=\\frac{18}{3}=6$.','Portanto, a afirmação está correta.']],
[17,'Unidade imaginária','Média','Sabendo que $i^2=-1$, calcule $i^{18}$.',['1','−1','i','−i'],1,['As potências de i se repetem a cada quatro expoentes: $i^4=1$.','Como $18=4\\cdot4+2$, temos $i^{18}=(i^4)^4i^2=-1$.']],
[18,'Teorema do resto','Média','Qual é o resto da divisão de $P(x)=x^3-2x+4$ por $x-2$?',['0','2','4','8'],3,['Pelo teorema do resto, o resto é $P(2)$.','$P(2)=2^3-2\\cdot2+4=8-4+4=8$.']],
[19,'Juros compostos','Difícil','Um capital de R$ 1.000,00 rende 10% ao período, em juros compostos, durante 2 períodos. Qual é o montante?',['R$ 1.100,00','R$ 1.200,00','R$ 1.210,00','R$ 1.220,00'],2,['Use $M=C(1+i)^n$.','$M=1000(1+0{,}10)^2=1000\\cdot1{,}21=1210$ reais.']]
];
const QUESTIONS=raw.map((r,i)=>({id:i+1,topic:TOPICS[r[0]][0],sub:r[1],difficulty:r[2],text:r[3],options:r[4],answer:r[5],steps:r[6],type:r[4].length===2?'Certo/errado':'Múltipla escolha',institution:'PRUMO — acervo autoral',exam:'Preparação geral — autoral',year:null,solution:'Texto'}));
function freshState(){return {favorites:[],attempts:[],lists:[],folders:[],exams:[],activeExam:null,name:'Estudante'}}
function latestAttempt(s,id){return [...s.attempts].reverse().find(a=>a.id===id)}
function matchesResolution(q,value){if(!value)return true;if(value==='Texto'||value==='Com solução em texto')return q.solution==='Texto';if(value==='Gabarito')return q.solution==='Gabarito';if(value==='Sem solução em texto')return q.solution!=='Texto';if(value==='Vídeo'||value==='Com solução por vídeo')return Boolean(q.video);if(value==='Vídeo e texto'||value==='Com solução em vídeo e texto')return Boolean(q.video)&&q.solution==='Texto';if(value==='Sem vídeo'||value==='Sem solução por vídeo')return !q.video;return true}
function filterValues(value){return Array.isArray(value)?value:value?[value]:[]}
function filterQuestions(s,f){return QUESTIONS.filter(q=>{const a=latestAttempt(s,q.id),types=filterValues(f.type),statuses=filterValues(f.status),resolutions=filterValues(f.resolution);return (!f.topics.length||f.topics.includes(q.topic)||f.topics.includes(q.sub))&&(!f.exam.length||f.exam.includes(q.exam))&&(!f.institution.length||(f.institution.includes(q.institution)||f.institution.includes(q.exam)))&&(!f.year.length||f.year.includes(String(q.year)))&&(!f.difficulty.length||f.difficulty.includes(q.difficulty))&&(!f.schooling?.length||f.schooling.includes(String(q.schooling)))&&(!types.length||types.includes(q.type))&&(!resolutions.length||resolutions.some(value=>matchesResolution(q,value)))&&(!f.favorites||s.favorites.includes(q.id))&&(!statuses.length||statuses.some(value=>value==='Não resolvidas'&&!a||value==='Já resolvidas'&&a||value==='Respondidas corretamente'&&a?.correct||value==='Respondidas incorretamente'&&a&&!a.correct))})}
function blankFilters(){return {topics:[],exam:[],institution:[],year:[],difficulty:[],schooling:[],type:'',status:'',resolution:'',favorites:false}}
function scoreExam(exam){let correct=0,wrong=0,blank=0;exam.ids.forEach(id=>{if(exam.answers[id]===undefined)blank++;else if(exam.answers[id]===QUESTIONS.find(q=>q.id===id).answer)correct++;else wrong++});return {correct,wrong,blank,rate:exam.ids.length?Math.round(correct/exam.ids.length*100):0}}
